      "Οναβοτουλινική τοξίνη: ενεργή ουρολοίμωξη, επίσχεση ούρων σε ασθενή που δεν μπορεί ή δεν θέλει να κάνει αυτοκαθετηριασμό.",
      "Οιστρογόνα: καρκίνος του μαστού ή του ενδομητρίου, αδιάγνωστη κολπική αιμορραγία."
