      "Νοραδρεναλίνη → α1 υποδοχείς (~70% α1A στον προστάτη) → Gq → IP3 → ↑ Ca²⁺ → σύσπαση → ↑ αντίσταση εξόδου.",
      "α1-ανταγωνιστής → χάλαση των ΛΜΙ → ↓ δυναμική απόφραξη → ↑ μέγιστη ροή ούρων κατά 2–3 ml/s και ↓ IPSS κατά 30–45% μέσα σε ημέρες έως εβδομάδες.",
      "Δεν μειώνουν τον όγκο του προστάτη (η «αντιαυξητική δράση» της διαφάνειας αφορά την επαγωγή απόπτωσης in vitro, με ασαφή κλινική σημασία) και δεν μειώνουν σημαντικά τον κίνδυνο ΟΕΚ ή χειρουργείου.",
      "Υπότυποι: α1A (προστάτης, αυχένας κύστης), α1B (λείοι μύες των αγγείων → ορθοστατική υπόταση), α1D (εξωστήρας, νωτιαίος μυελός → συμπτώματα αποθήκευσης). Μη εκλεκτικοί: τεραζοσίνη, δοξαζοσίνη (και αντιυπερτασικά). α1A-εκλεκτικοί: ταμσουλοζίνη, σιλοδοσίνη. Λειτουργικά ουροεκλεκτική: αλφουζοσίνη."
