      "Συνδυασμός με αναστολέα της 5α-αναγωγάσης σε μεγάλο προστάτη (> 30–40 ml) ή ειδικό προστατικό αντιγόνο ≥ 1,5 ng/ml (μελέτες MTOPS, CombAT).",
      "Δοκιμή αφαίρεσης του καθετήρα μετά από ΟΕΚ. Διευκόλυνση της αποβολής λίθων του κάτω ουρητήρα (εκτός ένδειξης, κυρίως ταμσουλοζίνη)."
