      "Τεραζοσίνη και δοξαζοσίνη: σταδιακή τιτλοποίηση από 1 mg, πρώτη δόση το βράδυ στο κρεβάτι. Αν διακοπούν για λίγες ημέρες, ξαναρχίζουν από την αρχική δόση.",
      "Συγχορήγηση με αναστολείς της PDE5: ο ασθενής πρέπει να είναι σταθερός στον α1-ανταγωνιστή και ο αναστολέας ξεκινά με τη μικρότερη δόση (αθροιστική υπόταση). Η ταμσουλοζίνη είναι η ασφαλέστερη επιλογή.",
      "ΚΥΠ με υπέρταση: η υπέρταση δεν αντιμετωπίζεται μόνο με α1-ανταγωνιστή. Στη μελέτη ALLHAT το σκέλος της δοξαζοσίνης διακόπηκε λόγω περισσότερης καρδιακής ανεπάρκειας.",
