      "Αιμοδοσία: όχι για 6 μήνες μετά την τελευταία δόση δουταστερίδης (μεγάλος χρόνος ημιζωής) και για 1 μήνα μετά τη φιναστερίδη, ώστε να μη μεταγγιστεί σε έγκυο."
